package us.drullk.graphmachine.worldgen;

import net.minecraft.core.registries.Registries;
import net.minecraft.resources.Identifier;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.level.dimension.DimensionType;
import us.drullk.graphmachine.GraphMachine;

/**
 * Keys of the dimension types this mod adds. The types themselves are data, generated by datagen.
 *
 * <p>Written by Claude Code; conversation transcript: {@code llm/transcripts/transcript_2026-10-16_23-43_3d80b42f-de61-4c60-b018-5e44e36d8860.md}.
 */
public final class GraphDimensionTypes {
    /**
     * A copy of the overworld dimension type. The graph world preset uses it so the client can tell a
     * graph level apart from any other level and draw the graph only there.
     */
    public static final ResourceKey<DimensionType> GRAPH = ResourceKey.create(Registries.DIMENSION_TYPE, Identifier.fromNamespaceAndPath(GraphMachine.MODID, "graph"));

    private GraphDimensionTypes() {
    }
}
